//! Regression test for the MCP resource-authorization bypass
//! (WIN-2041, GHSA-7qg3-pr4g-cq5x).
//!
//! Invariant: the AI Agent worker (`load_mcp_tools`) must load an MCP resource
//! only when the job identity is allowed to read it — the same
//! `resources:read:{path}` + RLS gate the regular MCP tools API (`get_mcp_tools`)
//! enforces. It loads the resource through the job's permissioned client
//! (`AuthedClient::get_resource_value`, the `resources/get_value` path), not the
//! raw DB pool. Otherwise a low-privileged user who can edit a flow could make
//! the agent load and use an MCP resource (URL + inline headers + token) they are
//! not allowed to read: a confused-deputy bypass.
//!
//! This test pins, against the `mcp_resource_authz` fixture (an MCP resource in
//! a folder only the admin can read):
//!   - a plain developer (test-user-3) is DENIED loading the private resource,
//!     before any MCP connection is attempted, and the resource never leaks;
//!   - an admin (test-user) clears the gate, the resource resolves, and loading
//!     only fails later at the connect step — proving no over-blocking.
#![cfg(feature = "mcp")]

use sqlx::{Pool, Postgres};
use windmill_common::client::AuthedClient;
use windmill_test_utils::*;
use windmill_worker::{load_mcp_tools, McpResourceConfig};

fn config(resource_path: &str) -> Vec<McpResourceConfig> {
    vec![McpResourceConfig {
        resource_path: resource_path.to_string(),
        include_tools: None,
        exclude_tools: None,
    }]
}

// The Ok variant ((HashMap<_, Arc<McpClient>>, Vec<Tool>)) does not implement
// Debug, so `expect_err` is unavailable — extract the error explicitly.
async fn load_err(db: &Pool<Postgres>, client: &AuthedClient, ctx: &str) -> String {
    load_err_for(db, client, "$res:f/private/admin_mcp", ctx).await
}

async fn load_err_for(
    db: &Pool<Postgres>,
    client: &AuthedClient,
    resource_path: &str,
    ctx: &str,
) -> String {
    match load_mcp_tools(db, "test-workspace", config(resource_path), client).await {
        Ok(_) => panic!("{ctx}"),
        Err(e) => e.to_string(),
    }
}

#[sqlx::test(fixtures("base", "mcp_resource_authz"))]
async fn test_mcp_resource_not_loaded_without_authorization(
    db: Pool<Postgres>,
) -> anyhow::Result<()> {
    initialize_tracing().await;

    let server = ApiServer::start(db.clone()).await?;
    let base_internal_url = format!("http://localhost:{}", server.addr.port());

    // ---- CORE REGRESSION: the developer cannot read the private MCP resource,
    //      so the worker must refuse to load it — before any MCP connection is
    //      attempted, and without the resource ever leaking.
    let dev_client = AuthedClient::new(
        base_internal_url.clone(),
        "test-workspace".to_string(),
        "SECRET_TOKEN_3".to_string(),
        None,
    );
    let msg = load_err(
        &db,
        &dev_client,
        "developer must be denied loading a resource they can't read",
    )
    .await;
    assert!(
        msg.contains("don't have access"),
        "denial should come from the resource-RLS gate, not a connection error: {msg}"
    );
    // An unauthorized caller must be blocked before MCP client creation, so no
    // resource material (URL, headers, token) is ever loaded for them.
    assert!(
        !msg.contains("Failed to create MCP client"),
        "developer must be blocked before the connection step (would mean the resource was loaded): {msg}"
    );

    // ---- NO OVER-BLOCKING: an admin clears the resource-RLS gate, so the
    //      resource resolves and loading only fails later at the connect step.
    let admin_client = AuthedClient::new(
        base_internal_url,
        "test-workspace".to_string(),
        "SECRET_TOKEN".to_string(),
        None,
    );
    let msg = load_err(
        &db,
        &admin_client,
        "the fixture URL is non-resolvable, so the connect step must fail",
    )
    .await;
    assert!(
        !msg.contains("don't have access"),
        "admin must clear the resource-RLS gate, not be denied: {msg}"
    );
    assert!(
        msg.contains("Failed to create MCP client"),
        "admin should resolve the resource and only fail at the connect step: {msg}"
    );

    Ok(())
}

/// A `$var:` in the resource's `url` is resolved before connecting, rather than
/// being handed to the client as a literal (and rejected as a relative URL).
#[sqlx::test(fixtures("base", "mcp_resource_authz"))]
async fn test_mcp_resource_url_variable_is_resolved(db: Pool<Postgres>) -> anyhow::Result<()> {
    initialize_tracing().await;

    let server = ApiServer::start(db.clone()).await?;
    let client = AuthedClient::new(
        format!("http://localhost:{}", server.addr.port()),
        "test-workspace".to_string(),
        "SECRET_TOKEN".to_string(),
        None,
    );
    let msg = load_err_for(
        &db,
        &client,
        "$res:u/test-user/var_mcp",
        "the variable's URL is non-resolvable, so the connect step must fail",
    )
    .await;
    assert!(
        msg.contains("mcp-from-var.invalid.windmill.test"),
        "the URL should come from the variable: {msg}"
    );

    Ok(())
}

//! End-to-end regression test for WIN-2161.
//!
//! Reproduces, through real product code, the state after a database-to-external
//! migration: a secret that was created under the database backend and then
//! *migrated* to an external backend (Azure Key Vault). Migration writes the
//! plaintext to the store but
//! leaves the encrypted ciphertext in `variable.value` (it never rewrites it to
//! a `$azure_kv:` marker). The bug: `clone_variables` only replicated
//! marker-valued secrets, so forking left the migrated secret unreplicated and
//! reads in the fork failed with "not found in Azure Key Vault".
//!
//! This drives the real `/migrate_secrets_to_azure_kv`, `/create_fork` and
//! `variables/get_value` endpoints against a local Azure Key Vault emulator
//! (lowkey-vault), which the `AzureKeyVaultBackend` talks to via its
//! static-token / self-signed-cert emulator mode.
//!
//! The test is `#[ignore]`d, so a plain `cargo test` skips it without creating
//! a database. Run it with `--ignored` (`AZURE_KV_URL` overrides the default
//! https://localhost:8443):
//! ```bash
//! podman run -d --name lowkey -p 8443:8443 \
//!     -e LOWKEY_ARGS="--LOWKEY_VAULT_NAMES=default" \
//!     docker.io/nagyesta/lowkey-vault:7.3.0
//!
//! cargo test -p windmill-api-integration-tests \
//!     --features private,enterprise --test fork_secret_replication_azure -- --ignored --nocapture
//! ```

#[cfg(all(feature = "private", feature = "enterprise"))]
mod azure_fork {
    use serde_json::json;
    use sqlx::{Pool, Postgres};
    use windmill_common::variables::{build_crypt, encrypt};
    use windmill_test_utils::*;

    fn client() -> reqwest::Client {
        reqwest::Client::new()
    }

    fn authed(builder: reqwest::RequestBuilder) -> reqwest::RequestBuilder {
        builder.header("Authorization", "Bearer SECRET_TOKEN")
    }

    fn vault_url() -> String {
        std::env::var("AZURE_KV_URL").unwrap_or_else(|_| "https://localhost:8443".to_string())
    }

    /// The Azure settings for the emulator: a static token switches the backend
    /// into emulator mode (no Entra ID, self-signed certs accepted).
    fn azure_settings() -> serde_json::Value {
        json!({
            "vault_url": vault_url(),
            "tenant_id": "emulator-tenant",
            "client_id": "emulator-client",
            "token": "emulator-token",
        })
    }

    #[sqlx::test(migrations = "../migrations", fixtures("base"))]
    #[ignore = "requires a lowkey-vault Azure Key Vault emulator at AZURE_KV_URL"]
    async fn migrated_secret_is_replicated_on_fork(db: Pool<Postgres>) -> anyhow::Result<()> {
        initialize_tracing().await;

        // The Azure KV emulator persists across runs; derive unique names per run
        // so a secret written by a previous run can't mask a regression.
        let suffix = uuid::Uuid::new_v4().simple().to_string();
        let short = &suffix[..8];
        let source_ws = "test-workspace";
        let path = format!("u/test-user/db_password_{short}");
        let path = path.as_str();
        let plaintext = "s3cr3t-value";

        let ciphertext = {
            let mc = build_crypt(&db, source_ws).await?;
            encrypt(&mc, plaintext)
        };
        sqlx::query(
            "INSERT INTO variable (workspace_id, path, value, is_secret, description, extra_perms)
             VALUES ($1, $2, $3, true, '', '{}')",
        )
        .bind(source_ws)
        .bind(path)
        .bind(&ciphertext)
        .execute(&db)
        .await?;

        sqlx::query(
            "INSERT INTO global_settings (name, value) VALUES ('secret_backend', $1)
             ON CONFLICT (name) DO UPDATE SET value = EXCLUDED.value",
        )
        .bind(json!({
            "type": "AzureKeyVault",
            "vault_url": vault_url(),
            "tenant_id": "emulator-tenant",
            "client_id": "emulator-client",
            "token": "emulator-token",
        }))
        .execute(&db)
        .await?;

        let server = ApiServer::start(db.clone()).await?;
        let port = server.addr.port();

        let resp = authed(client().post(format!(
            "http://localhost:{port}/api/settings/migrate_secrets_to_azure_kv"
        )))
        .json(&azure_settings())
        .send()
        .await?;
        let status = resp.status();
        let body = resp.text().await?;
        assert_eq!(status, 200, "migrate_secrets_to_azure_kv failed: {body}");
        let report: serde_json::Value = serde_json::from_str(&body)?;
        assert!(
            report["migrated_count"].as_i64().unwrap_or(0) >= 1,
            "expected at least one migrated secret: {report}"
        );

        // Assert the source resolves before forking, so a fork-read failure is
        // attributable to replication rather than a broken seed.
        let resp = authed(client().get(format!(
            "http://localhost:{port}/api/w/{source_ws}/variables/get_value/{path}"
        )))
        .send()
        .await?;
        assert_eq!(resp.status(), 200, "source read: {}", resp.text().await?);
        assert_eq!(resp.json::<String>().await?, plaintext);

        let fork_ws = format!("wm-fork-az{short}");
        let fork_ws = fork_ws.as_str();
        let resp = authed(client().post(format!(
            "http://localhost:{port}/api/w/{source_ws}/workspaces/create_fork"
        )))
        .json(&json!({ "id": fork_ws, "name": "Azure Fork Test" }))
        .send()
        .await?;
        assert_eq!(resp.status(), 200, "create_fork: {}", resp.text().await?);

        // The fork resolves the secret only if it was replicated under the fork's
        // own workspace-id key in the external store.
        let resp = authed(client().get(format!(
            "http://localhost:{port}/api/w/{fork_ws}/variables/get_value/{path}"
        )))
        .send()
        .await?;
        let status = resp.status();
        let body = resp.text().await?;
        assert_eq!(
            status, 200,
            "forked secret must resolve, got {status}: {body}"
        );
        assert_eq!(
            serde_json::from_str::<String>(&body)?,
            plaintext,
            "fork should return the replicated plaintext"
        );

        Ok(())
    }
}

use serde_json::json;
use sqlx::{Pool, Postgres};
use windmill_test_utils::*;

fn client() -> reqwest::Client {
    reqwest::Client::new()
}

fn authed(builder: reqwest::RequestBuilder) -> reqwest::RequestBuilder {
    builder.header("Authorization", "Bearer SECRET_TOKEN")
}

fn assert_2xx(status: u16, body: &str, endpoint: &str) {
    assert!(
        (200..300).contains(&status),
        "{endpoint} returned {status}: {body}",
    );
}

#[sqlx::test(migrations = "../migrations", fixtures("base"))]
async fn test_capture_endpoints(db: Pool<Postgres>) -> anyhow::Result<()> {
    initialize_tracing().await;
    let server = ApiServer::start(db.clone()).await?;
    let port = server.addr.port();

    // POST /capture/set_config → 200 (authed)
    let resp = authed(
        client()
            .post(format!(
                "http://localhost:{port}/api/w/test-workspace/capture/set_config"
            ))
            .json(&json!({
                "trigger_kind": "webhook",
                "path": "u/test-user/test_capture",
                "is_flow": false
            })),
    )
    .send()
    .await?;
    let status = resp.status().as_u16();
    let body = resp.text().await?;
    assert_2xx(status, &body, "POST /capture/set_config");

    // GET /capture/list/{...} → 200 (authed)
    let resp = authed(client().get(format!(
        "http://localhost:{port}/api/w/test-workspace/capture/list/script/u/test-user/test_capture"
    )))
    .send()
    .await?;
    let status = resp.status().as_u16();
    let body = resp.text().await?;
    assert_2xx(
        status,
        &body,
        "GET /capture/list/script/u/test-user/test_capture",
    );

    // POST /capture/ping_config/{trigger_kind}/{runnable_kind}/{*path} → 200
    let resp = authed(client().post(format!(
        "http://localhost:{port}/api/w/test-workspace/capture/ping_config/webhook/script/u/test-user/test_capture"
    )))
    .send()
    .await?;
    assert_2xx(
        resp.status().as_u16(),
        &resp.text().await?,
        "POST /capture/ping_config",
    );

    // GET /capture/get_configs/{runnable_kind}/{*path} → 200
    let resp = authed(client().get(format!(
        "http://localhost:{port}/api/w/test-workspace/capture/get_configs/script/u/test-user/test_capture"
    )))
    .send()
    .await?;
    assert_2xx(
        resp.status().as_u16(),
        &resp.text().await?,
        "GET /capture/get_configs",
    );

    Ok(())
}

//! Regression tests for GHSA-vm75-gmpw-rvp9: the unauthenticated `/api/slack` callback must
//! not be drivable into decrypting arbitrary workspace variables.
//!
//! The OpenModal branch reaches `get_slack_token` (a privileged, RLS-bypassing variable
//! decryption). It is now gated by a per-workspace HMAC over (w_id, job_id, path) — the same
//! workspace key used to sign resume URLs. Without a valid signature the request is rejected
//! with 401 before any decryption, even when `SLACK_SIGNING_SECRET` is unset (the default).

use hmac::{Hmac, Mac};
use serde_json::json;
use sha2::Sha256;
use sqlx::{Pool, Postgres};
use uuid::Uuid;
use windmill_test_utils::*;

fn client() -> reqwest::Client {
    reqwest::Client::new()
}

/// Re-implementation of the server's `sign_slack_payload` for the positive-control test.
/// The fixture sets `workspace_key.key = 'test-key'` for `test-workspace`.
fn sign(w_id: &str, parts: &[&[u8]]) -> String {
    let mut mac = Hmac::<Sha256>::new_from_slice(b"test-key").unwrap();
    mac.update(b"slack_payload_v1\0"); // SLACK_PAYLOAD_HMAC_DOMAIN
    mac.update(w_id.as_bytes());
    for p in parts {
        mac.update(b"\0");
        mac.update(p);
    }
    hex::encode(mac.finalize().into_bytes())
}

/// POST an `open_modal` block action to the unauthenticated `/api/slack` callback.
async fn post_open_modal(port: u16, value: serde_json::Value) -> reqwest::Response {
    let payload = json!({
        "type": "block_actions",
        "trigger_id": "trigger-123",
        "container": { "message_ts": "0", "channel_id": "C1" },
        "actions": [ { "action_id": "open_modal", "value": value.to_string() } ],
    });
    client()
        .post(format!("http://localhost:{port}/api/slack"))
        .form(&[("payload", payload.to_string())])
        .send()
        .await
        .unwrap()
}

/// POST a `view_submission` to the unauthenticated `/api/slack` callback with the given
/// private_metadata.
async fn post_view_submission(port: u16, private_metadata: serde_json::Value) -> reqwest::Response {
    let payload = json!({
        "type": "view_submission",
        "view": {
            "state": { "values": {} },
            "private_metadata": private_metadata.to_string(),
        },
    });
    client()
        .post(format!("http://localhost:{port}/api/slack"))
        .form(&[("payload", payload.to_string())])
        .send()
        .await
        .unwrap()
}

/// A submission with an unsigned (or tampered) `private_metadata` must be rejected with 401
/// BEFORE the resume/cancel action runs — the signature gate is checked first. The resume_url
/// here is well-formed (so it parses) but never acted upon.
#[sqlx::test(migrations = "../migrations", fixtures("base"))]
async fn test_view_submission_without_signature_is_rejected(
    db: Pool<Postgres>,
) -> anyhow::Result<()> {
    initialize_tracing().await;
    let server = ApiServer::start(db.clone()).await?;
    let port = server.addr.port();
    let job_id = Uuid::new_v4();
    let resume_url = format!("/api/w/test-workspace/jobs_u/resume/{job_id}/1/deadbeef");

    let resp = post_view_submission(
        port,
        json!({
            "resume_url": resume_url,
            "resource_path": "u/admin/secret",
            "container": { "message_ts": "0", "channel_id": "C1" },
            "hide_cancel": false,
        }),
    )
    .await;
    assert_eq!(
        resp.status(),
        401,
        "unsigned submission must be rejected before the resume action"
    );

    Ok(())
}

#[sqlx::test(migrations = "../migrations", fixtures("base"))]
async fn test_open_modal_without_signature_is_rejected(db: Pool<Postgres>) -> anyhow::Result<()> {
    initialize_tracing().await;
    let server = ApiServer::start(db.clone()).await?;
    let port = server.addr.port();
    let job_id = Uuid::new_v4();

    // No signature → must be rejected with 401 before any variable lookup. Before the fix
    // this reached `get_slack_token` and forced decryption of `u/admin/secret`.
    let resp = post_open_modal(
        port,
        json!({
            "w_id": "test-workspace",
            "job_id": job_id.to_string(),
            "path": "u/admin/secret",
            "flow_step_id": "a",
        }),
    )
    .await;
    assert_eq!(
        resp.status(),
        401,
        "unsigned OpenModal callback must be rejected"
    );

    Ok(())
}

#[sqlx::test(migrations = "../migrations", fixtures("base"))]
async fn test_open_modal_with_wrong_signature_is_rejected(
    db: Pool<Postgres>,
) -> anyhow::Result<()> {
    initialize_tracing().await;
    let server = ApiServer::start(db.clone()).await?;
    let port = server.addr.port();
    let job_id = Uuid::new_v4();

    let resp = post_open_modal(
        port,
        json!({
            "w_id": "test-workspace",
            "job_id": job_id.to_string(),
            "path": "u/admin/secret",
            "flow_step_id": "a",
            "signature": "deadbeef",
        }),
    )
    .await;
    assert_eq!(
        resp.status(),
        401,
        "OpenModal callback with an invalid signature must be rejected"
    );

    Ok(())
}

#[sqlx::test(migrations = "../migrations", fixtures("base"))]
async fn test_open_modal_with_tampered_path_is_rejected(db: Pool<Postgres>) -> anyhow::Result<()> {
    initialize_tracing().await;
    let server = ApiServer::start(db.clone()).await?;
    let port = server.addr.port();
    let job_id = Uuid::new_v4();

    // A signature legitimately minted for one path cannot be reused to decrypt another: the
    // path is bound into the HMAC.
    let signature = sign(
        "test-workspace",
        &[job_id.to_string().as_bytes(), b"u/admin/legit_resource"],
    );
    let resp = post_open_modal(
        port,
        json!({
            "w_id": "test-workspace",
            "job_id": job_id.to_string(),
            "path": "u/admin/some_other_secret",
            "flow_step_id": "a",
            "signature": signature,
        }),
    )
    .await;
    assert_eq!(
        resp.status(),
        401,
        "a signature bound to a different path must not authorize decryption"
    );

    Ok(())
}

#[sqlx::test(migrations = "../migrations", fixtures("base"))]
async fn test_open_modal_with_valid_signature_passes_the_gate(
    db: Pool<Postgres>,
) -> anyhow::Result<()> {
    initialize_tracing().await;
    let server = ApiServer::start(db.clone()).await?;
    let port = server.addr.port();
    let job_id = Uuid::new_v4();
    let path = "u/admin/nonexistent_resource";

    // A correctly signed payload passes the authorization gate and proceeds to resolve the
    // slack resource. The resource does not exist, so the handler returns a generic 400
    // ("Invalid Slack callback request") rather than 401 — proving the gate accepted the
    // signature (so the fix does not simply reject everything) without echoing the path.
    let signature = sign(
        "test-workspace",
        &[job_id.to_string().as_bytes(), path.as_bytes()],
    );
    let resp = post_open_modal(
        port,
        json!({
            "w_id": "test-workspace",
            "job_id": job_id.to_string(),
            "path": path,
            "flow_step_id": "a",
            "signature": signature,
        }),
    )
    .await;
    let status = resp.status();
    let body = resp.text().await?;
    assert_eq!(
        status, 400,
        "validly signed callback should pass the gate and 400 on the missing resource, got {status}: {body}"
    );
    assert!(
        !body.contains("nonexistent_resource"),
        "error must not echo the probed path: {body}"
    );

    Ok(())
}

use serde_json::json;
use sqlx::{Pool, Postgres};
use uuid::Uuid;
use windmill_test_utils::*;

fn client() -> reqwest::Client {
    reqwest::Client::new()
}

fn authed(builder: reqwest::RequestBuilder) -> reqwest::RequestBuilder {
    builder.header("Authorization", "Bearer SECRET_TOKEN")
}

fn assert_2xx(status: u16, body: &str, endpoint: &str) {
    assert!(
        (200..300).contains(&status),
        "{endpoint} returned {status}: {body}",
    );
}

/// Insert a minimal completed job directly into the database for testing.
async fn insert_completed_job(db: &Pool<Postgres>) -> Uuid {
    let id = Uuid::new_v4();
    sqlx::query(
        "INSERT INTO v2_job (id, workspace_id, created_by, permissioned_as, kind, tag, args)
         VALUES ($1, 'test-workspace', 'test-user', 'u/test-user', 'script', 'deno', '{}'::jsonb)",
    )
    .bind(id)
    .execute(db)
    .await
    .unwrap();

    sqlx::query(
        "INSERT INTO v2_job_completed (id, workspace_id, duration_ms, result, status)
         VALUES ($1, 'test-workspace', 100, '42'::jsonb, 'success')",
    )
    .bind(id)
    .execute(db)
    .await
    .unwrap();

    id
}

#[sqlx::test(migrations = "../migrations", fixtures("base"))]
async fn test_jobs_unauthed_endpoints(db: Pool<Postgres>) -> anyhow::Result<()> {
    initialize_tracing().await;
    let server = ApiServer::start(db.clone()).await?;
    let port = server.addr.port();
    let base = format!("http://localhost:{port}/api/w/test-workspace/jobs_u");

    let job_id = insert_completed_job(&db).await;

    // --- No-data endpoints ---

    let resp = authed(client().post(format!("{base}/queue/get_started_at_by_ids")))
        .json(&json!([]))
        .send()
        .await?;
    assert_2xx(
        resp.status().as_u16(),
        &resp.text().await?,
        "POST /queue/get_started_at_by_ids",
    );

    // --- Completed job endpoints (unauthed service, with auth header) ---

    let resp = authed(client().get(format!("{base}/get/{job_id}")))
        .send()
        .await?;
    assert_2xx(resp.status().as_u16(), &resp.text().await?, "GET /get");

    let resp = authed(client().get(format!("{base}/get_logs/{job_id}")))
        .send()
        .await?;
    assert_2xx(resp.status().as_u16(), &resp.text().await?, "GET /get_logs");

